def start_trials_for_existing_organizations(apps, schema_editor):
    """Every pre-existing organization gets a fresh trial starting now.

    MVP with no paying hotels: nobody should wake up expired because their org
    row predates the trial clock.
    """
    Organization = apps.get_model("api", "Organization")
    Subscription = apps.get_model("api", "Subscription")
    SubscriptionEvent = apps.get_model("api", "SubscriptionEvent")
    trial_ends_at = timezone.now() + timedelta(days=settings.SUBSCRIPTION_TRIAL_DAYS)
    for organization in Organization.objects.filter(subscription__isnull=True).iterator():
        subscription = Subscription.objects.create(
            organization=organization, trial_ends_at=trial_ends_at
        )
        SubscriptionEvent.objects.create(
            subscription=subscription,
            kind="TRIAL_STARTED",
            new_trial_ends_at=trial_ends_at,
            note="Backfilled when subscriptions were introduced.",
        )


